from polish_screens import A,P,put,toolbar,label

def polish_editor():
    xmlns=f'xmlns:android="{A}" xmlns:app="{P}"'
    def button(id,title,extra='',primary=False):
        return f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/{"PrimaryButton" if primary else "TextButton"}" android:layout_width="0dp" android:layout_weight="1" android:layout_height="44dp" android:text="{title}" android:textSize="13sp" android:letterSpacing="0" android:paddingHorizontal="4dp" {extra}/>'
    history='<LinearLayout android:layout_width="match_parent" android:layout_height="44dp" android:orientation="horizontal" android:paddingHorizontal="12dp">'+button('undo','Hoàn tác')+button('redo','Làm lại')+button('resetEditor','Khôi phục gốc')+'</LinearLayout>'
    canvas='<FrameLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:layout_marginHorizontal="16dp" android:layout_marginVertical="8dp"><com.example.appanh.editor.EditorCanvasView android:id="@+id/photo" android:layout_width="match_parent" android:layout_height="match_parent" android:padding="8dp"/><ProgressBar android:id="@+id/editorBusy" android:layout_width="36dp" android:layout_height="36dp" android:layout_gravity="center"/></FrameLayout>'
    tools='<LinearLayout android:layout_width="match_parent" android:layout_height="60dp" android:orientation="horizontal">'+''.join(f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/TextButton" android:layout_width="0dp" android:layout_weight="1" android:layout_height="60dp" android:text="{title}" android:textSize="12sp" android:paddingHorizontal="0dp" app:icon="@drawable/{icon}" app:iconGravity="textTop" app:iconSize="21dp" app:iconTint="@color/text_primary" android:textColor="@color/text_primary"/>' for id,title,icon in [('crop','Cắt','ic_crop'),('filter','Bộ lọc','ic_filter'),('adjust','Điều chỉnh','ic_settings'),('draw','Vẽ','ic_edit')])+'</LinearLayout>'
    crop='<LinearLayout android:id="@+id/cropPanel" android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:visibility="gone"><LinearLayout android:layout_width="match_parent" android:layout_height="44dp" android:orientation="horizontal">'+''.join(button(id,title) for id,title in [('ratioFree','Tự do'),('ratioSquare','1:1'),('ratioPortrait','4:3'),('ratioWide','16:9')])+'</LinearLayout><LinearLayout android:layout_width="match_parent" android:layout_height="44dp" android:orientation="horizontal">'+button('rotate','Xoay 90°')+button('applyCrop','Áp dụng cắt')+'</LinearLayout></LinearLayout>'
    filters='<HorizontalScrollView android:id="@+id/filterPanel" android:layout_width="match_parent" android:layout_height="48dp" android:visibility="gone" android:scrollbars="none"><LinearLayout android:layout_width="wrap_content" android:layout_height="match_parent" android:orientation="horizontal">'+''.join(f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/TextButton" android:layout_width="wrap_content" android:layout_height="44dp" android:text="{title}" android:textSize="13sp"/>' for id,title in [('filterOriginal','Gốc'),('filterMono','Trắng đen'),('filterSepia','Cổ điển'),('filterWarm','Ấm'),('filterCool','Lạnh')])+'</LinearLayout></HorizontalScrollView>'
    adjustment='<LinearLayout android:id="@+id/adjustPanel" android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:visibility="gone">'+''.join('<LinearLayout android:layout_width="match_parent" android:layout_height="44dp" android:orientation="horizontal" android:gravity="center_vertical"><TextView android:layout_width="86dp" android:layout_height="wrap_content" android:text="'+title+'" android:textSize="13sp" android:textColor="@color/text_secondary"/><SeekBar android:id="@+id/'+id+'" android:layout_width="0dp" android:layout_weight="1" android:layout_height="44dp" android:max="'+str(maximum)+'" android:progress="'+str(progress)+'"/></LinearLayout>' for id,title,maximum,progress in [('brightness','Độ sáng',200,100),('contrast','Tương phản',150,50)])+'</LinearLayout>'
    palette='<LinearLayout android:layout_width="match_parent" android:layout_height="44dp" android:orientation="horizontal" android:gravity="center">'+''.join(f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/PrimaryButton" android:layout_width="36dp" android:layout_height="36dp" android:layout_marginHorizontal="5dp" android:minWidth="0dp" android:padding="0dp" android:backgroundTint="{color}" android:contentDescription="{title}" app:cornerRadius="18dp" app:strokeWidth="1dp" app:strokeColor="@color/field_border"/>' for id,color,title in [('brushWhite','@color/white','Bút trắng'),('brushBlack','@color/black','Bút đen'),('brushRed','#EF4444','Bút đỏ'),('brushBlue','#2563EB','Bút xanh dương'),('brushGreen','#16A34A','Bút xanh lá'),('brushYellow','#FACC15','Bút vàng')])+'</LinearLayout>'
    drawing='<LinearLayout android:id="@+id/drawPanel" android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:visibility="gone">'+palette+'<LinearLayout android:layout_width="match_parent" android:layout_height="44dp" android:orientation="horizontal" android:gravity="center_vertical"><TextView android:layout_width="56dp" android:layout_height="wrap_content" android:text="Nét bút" android:textColor="@color/text_secondary" android:textSize="13sp"/><SeekBar android:id="@+id/brushWidth" android:layout_width="0dp" android:layout_weight="1" android:layout_height="44dp" android:max="29" android:progress="5"/><com.google.android.material.button.MaterialButton android:id="@+id/clearDrawing" style="@style/TextButton" android:layout_width="92dp" android:layout_height="44dp" android:text="Xóa nét" android:textSize="13sp"/></LinearLayout></LinearLayout>'
    controls=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingHorizontal="16dp" android:background="@color/viewer_controls">{crop}{filters}{adjustment}{drawing}</LinearLayout>'
    footer='<LinearLayout android:layout_width="match_parent" android:layout_height="64dp" android:paddingHorizontal="16dp" android:paddingVertical="8dp" android:orientation="horizontal">'+button('cancelEdit','Hủy','android:layout_marginEnd="8dp"')+button('save','Lưu bản sao',primary=True)+'</LinearLayout>'
    put('layout/activity_edit_photo.xml',f'<LinearLayout {xmlns} android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/viewer_background">{toolbar("Chỉnh sửa")}{history}{canvas}{tools}{controls}'+label('',13,'@color/text_secondary','android:id="@+id/status" android:paddingHorizontal="20dp" android:layout_marginTop="4dp" android:maxLines="2" android:ellipsize="end"')+footer+'</LinearLayout>')

if __name__=='__main__':polish_editor()
